/**
 * The homepage's showcase on a docs page: two rows of films made with HyperFrames, drifting in opposite directions.
 * As on the homepage (web-marketing HyperFramesShowcase), a row can be dragged, swiped sideways on a trackpad or moved
 * with shift+wheel, and keyboard focus brings a card into view. The card nearest the middle plays its 720p copy, the
 * others show their poster; a click opens the full film with sound. Reduced motion holds the rows still on their
 * posters and lets them scroll natively.
 */
export const FilmRows = () => {
  // Keep data inside the component: Mintlify compiles only the named export.
  const CDN = "https://static.heygen.ai/hyperframes-oss";
  const film = (id, kind, name, ar) => ({
    kind,
    name,
    ar,
    src: `${CDN}/homepage/showcase/card/${id}-v1.mp4`,
    hq: `${CDN}/homepage/showcase/hq/${id}-v1.mp4`,
    poster: `${CDN}/homepage/showcase/poster/${id}-v1.jpg`,
  });
  const launch = `${CDN}/site/studio-launch-nib-sf-audio`;
  const rows = [
    [
      { ...film("studio-launch", "Launch film", "Studio launch", 16 / 9), hq: `${launch}.mp4`, poster: `${launch}-poster.jpg` },
      film("vfx-billboard-hoodie-handoff", "VFX", "Out of the billboard", 9 / 16),
      film("frameys-opening-night", "Awards trailer", "Opening night", 16 / 9),
      film("jake-taycan-bricks", "3D build", "Jake & the Taycan", 1),
      film("cartoon-frameys-launch-one-take", "Cartoon", "The Frameys", 16 / 9),
      film("k", "Explainer", "The journey of “k”", 9 / 16),
      film("real-ui-newspaper-1969", "Real UI", "Men walk on the Moon", 16 / 9),
      film("launch-storyboard-first", "Product launch", "Storyboard first", 16 / 9),
      film("captions", "Captions", "Don’t tell my clients", 4 / 5),
      film("manga-last-onigiri", "Manga", "The last onigiri", 16 / 9),
      film("square-one-strudel", "Live-coded music", "Square one", 1),
      film("vfx-background-removal-launch", "VFX", "Background removal", 16 / 9),
      film("sitcom", "Sitcom", "Two lines", 9 / 16),
      film("just-html", "Explainer", "It’s just HTML", 16 / 9),
      film("kinetic-type-curiosity", "Kinetic type", "Going through a change", 4 / 3),
      film("home", "Many looks", "This homepage", 16 / 9),
      film("wordmark-sting", "Logo sting", "Wordmark", 1),
      film("session-story", "Cartoon", "Jake’s favorite agent", 16 / 9),
      film("launch-claude-motion", "Square", "Claude Motion", 1),
      film("real-ui-google-search", "Real UI", "How do cameras focus", 16 / 9),
      film("muybridge-horse-styles", "Style study", "One horse, many looks", 32 / 9),
      film("rackrats", "Cartoon", "Rackrats", 16 / 9),
    ],
    [
      film("tutorial-wenbo-studio-tutorial-talkinghead", "Tutorial", "Reference any video", 16 / 9),
      film("axe", "3D tutorial", "Axe chop", 9 / 16),
      film("framey-orby-halloween", "Cartoon", "Halloween party", 16 / 9),
      film("cow", "Launch parody", "Cow 1.0", 16 / 9),
      film("ascii-sharks-logo", "Logo sting", "ASCII sharks", 16 / 9),
      film("vfx-giant-keyboard-reel", "VFX", "Giant keyboard", 9 / 16),
      film("real-ui-wikipedia", "Real UI", "Wikipedia", 16 / 9),
      film("launch-heygen-video1", "AI footage", "HeyGen Video 1", 16 / 9),
      film("pixel-game-one-canvas", "Code tutorial", "A game in one canvas", 16 / 9),
      film("demo", "Talking head", "Tool demo", 9 / 16),
      film("everything-was-written", "Motion design", "Everything was written", 16 / 9),
      film("launch", "Kinetic type", "Keynote line", 16 / 9),
      film("remotion-to-hyperframes", "3D voxel", "Remotion to HyperFrames", 16 / 9),
      film("explainer-code2video-bench", "Presenter", "Code2Video Bench", 16 / 9),
      film("real-ui-cctv", "Real UI", "CCTV tracking", 16 / 9),
      film("frameys-felt-party", "3D characters", "The Frameys dance", 16 / 9),
      film("launch-moments-catalog", "Product launch", "Moments catalog", 16 / 9),
      film("shards-logo-reveal", "Logo reveal", "Shards", 16 / 9),
      film("launch-hyperframes-studio-intro", "Product reveal", "Studio intro", 16 / 9),
      film("studio-launch-pixel", "Launch film", "A launch video in 6 hours", 16 / 9),
      film("youtube-online-business", "YouTube edit", "Online business story", 16 / 9),
      film("website-to-launch", "Product launch", "From your website", 16 / 9),
      film("generative-replica", "Generative art", "Code is a material", 16 / 9),
    ],
  ];

  const rootRef = useRef(null);
  const dialogRef = useRef(null);
  const [open, setOpen] = useState(null);
  const [paused, setPaused] = useState(false);
  const pausedRef = useRef(paused);
  pausedRef.current = paused;
  // Known on the first render, so nothing loads or moves before the preference is read.
  const [still, setStill] = useState(
    () => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches,
  );

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const follow = (event) => setStill(event.matches);
    query.addEventListener("change", follow);
    return () => query.removeEventListener("change", follow);
  }, []);

  // A card loads its file only near the screen, and one plays at a time, the one nearest the middle: with two 720p
  // films playing, Chrome drops the whole page from 120 to 30 fps (measured 2026-10-26), drift or not.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    // Reduce Motion turned on mid-visit: stop every film and let go of its file.
    if (still) {
      for (const v of root.querySelectorAll("video[data-src]")) {
        v.pause();
        v.removeAttribute("src");
        v.load();
      }
      return;
    }
    const near = new Set();
    const seen = new IntersectionObserver((entries) => {
      for (const { target, isIntersecting } of entries) {
        if (isIntersecting) {
          if (!target.src) target.src = target.dataset.src;
          near.add(target);
        } else if (target.src) {
          near.delete(target);
          target.pause();
          target.removeAttribute("src");
          target.load();
        }
      }
    }, { rootMargin: "100px" });
    for (const v of root.querySelectorAll("video[data-src]")) seen.observe(v);
    const pick = () => {
      const mid = window.innerWidth / 2;
      const centre = (v) => { const r = v.getBoundingClientRect(); return Math.abs(r.left + r.width / 2 - mid); };
      // Paused rows, or a full film open in the dialog: no preview plays.
      // A film playing with sound anywhere on the page (a chosen remix, a replica pair) also rests the previews.
      const filmWithSound = [...document.querySelectorAll("video")].some((v) => !v.paused && !v.muted);
      const resting = root.classList.contains("is-paused") || root.dataset.watching === "true" || filmWithSound;
      const first = resting ? null : [...near].sort((a, b) => centre(a) - centre(b))[0];
      for (const v of near) {
        if (v === first) v.play().catch(() => {});
        else v.pause();
      }
    };
    const tick = setInterval(pick, 1000);
    return () => { seen.disconnect(); clearInterval(tick); };
  }, [still]);

  // Each row drifts by a transform the script moves (seconds per loop: 90 and 105), so a hand can move it too.
  useEffect(() => {
    const root = rootRef.current;
    if (!root || still) return;
    const ac = new AbortController();
    const on = { signal: ac.signal };
    const stops = [...root.querySelectorAll(".hf-film-track")].map((row, r) => {
      const dir = r ? 1 : -1;
      const seconds = r ? 105 : 90;
      let x = 0;
      let fling = 0;
      let last = 0;
      let raf = 0;
      let moved = 0;
      let focused = false;
      let drag = null;
      // one loop = from a card to its twin in the second copy, gap included
      const period = () => {
        const cards = row.children;
        return cards[cards.length / 2].offsetLeft - cards[0].offsetLeft;
      };
      const tick = (now) => {
        const dt = Math.min(0.05, (now - last) / 1000);
        last = now;
        const loop = period();
        if (!drag?.on) {
          x += fling;
          fling = Math.abs(fling) < 0.05 ? 0 : fling * 0.86;
          if (!pausedRef.current && !focused) x += (loop / seconds) * dt;
        }
        x = ((x % loop) + loop) % loop;
        row.parentElement.scrollLeft = 0; // focus may scroll the clipped row; the transform alone places it
        row.style.transform = `translateX(${(dir < 0 ? -x : x - loop).toFixed(1)}px)`;
        raf = requestAnimationFrame(tick);
      };
      // only animates on screen
      const seen = new IntersectionObserver(([entry]) => {
        cancelAnimationFrame(raf);
        if (entry.isIntersecting) {
          last = performance.now();
          raf = requestAnimationFrame(tick);
        }
      });
      seen.observe(row);
      // a keyboard-focused card holds the row still, centred
      row.addEventListener("focusin", (e) => {
        if (!e.target.matches(":focus-visible")) return;
        focused = true;
        const into = (row.parentElement.clientWidth - e.target.offsetWidth) / 2;
        const shift = Math.max(0.5, e.target.offsetLeft - into);
        x = dir < 0 ? shift : period() - shift;
      }, on);
      row.addEventListener("focusout", () => (focused = false), on);
      // a press is a click until it moves 6px; then the row takes the pointer and becomes a drag
      row.addEventListener("pointerdown", (e) => {
        drag = { x: e.clientX, x0: x, id: e.pointerId, on: false };
        moved = 0;
        fling = 0;
      }, on);
      row.addEventListener("pointermove", (e) => {
        if (!drag) return;
        const dx = e.clientX - drag.x;
        moved = Math.max(moved, Math.abs(dx));
        if (!drag.on && moved > 6) {
          drag.on = true;
          row.setPointerCapture(drag.id);
          row.classList.add("is-dragging");
        }
        if (drag.on) x = drag.x0 + dx * dir;
      }, on);
      const end = () => {
        drag = null;
        row.classList.remove("is-dragging");
      };
      window.addEventListener("pointerup", end, on);
      window.addEventListener("pointercancel", end, on);
      row.addEventListener("lostpointercapture", end, on);
      // the click that ends a drag doesn't open a film; Enter and Space (detail 0) always do
      row.addEventListener("click", (e) => {
        if (e.detail > 0 && moved > 6) {
          e.stopPropagation();
          e.preventDefault();
        }
        moved = 0;
      }, { capture: true, signal: ac.signal });
      // a sideways swipe or shift+wheel moves the row; a plain vertical wheel still scrolls the page
      row.addEventListener("wheel", (e) => {
        const d = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.shiftKey ? e.deltaY : 0;
        if (!d) return;
        e.preventDefault();
        fling += d * -dir;
      }, { passive: false, signal: ac.signal });
      return () => {
        cancelAnimationFrame(raf);
        seen.disconnect();
        row.style.transform = "";
      };
    });
    return () => {
      ac.abort();
      for (const stop of stops) stop();
    };
  }, [still]);

  useEffect(() => {
    if (paused) for (const v of rootRef.current?.querySelectorAll("video") ?? []) v.pause();
  }, [paused]);

  // While a full film plays in the dialog, the previews stop, so only one film plays at a time.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.dataset.watching = open ? "true" : "false";
    if (open) for (const v of root.querySelectorAll("video[data-src]")) v.pause();
  }, [open]);

  useEffect(() => {
    const d = dialogRef.current;
    if (!d) return;
    if (open && !d.open) d.showModal();
    if (!open && d.open) d.close();
  }, [open]);

  const card = (f, i, twin) => (
    <button
      type="button"
      key={(twin ? "t" : "") + i}
      className="hf-film-card"
      style={{ aspectRatio: String(f.ar) }}
      aria-hidden={twin ? "true" : undefined}
      tabIndex={twin ? -1 : 0}
      onClick={() => setOpen(f)}
      aria-label={`${f.kind}: ${f.name}. Watch with sound`}
    >
      <video data-src={f.src} poster={f.poster} muted loop playsInline preload="none" />
      <span className="hf-film-label"><b>{f.kind}</b> {f.name}</span>
    </button>
  );

  return (
    <div className={"hf-film-rows not-prose" + (paused ? " is-paused" : "")} ref={rootRef}>
      {rows.map((row, r) => (
        <div className={"hf-film-row" + (r ? " is-reverse" : "")} key={r}>
          <div className="hf-film-track">
            {row.map((f, i) => card(f, i, false))}
            {row.map((f, i) => card(f, i, true))}
          </div>
        </div>
      ))}
      {/* WCAG 2.2.2: rows that move on their own get a way to stop them. Reduced motion never moves them, so no button */}
      {!still && (
        <button type="button" className="hf-film-pause" aria-pressed={paused} onClick={() => setPaused(!paused)}>
          {paused ? "Play" : "Pause"}
        </button>
      )}
      <dialog ref={dialogRef} className="hf-film-dialog" onClose={() => setOpen(null)} onClick={(e) => { if (e.target === dialogRef.current) setOpen(null); }}>
        {open && (
          <div>
            <video src={open.hq} poster={open.poster} controls autoPlay playsInline />
            <div className="hf-film-dialog-bar">
              <span><b>{open.kind}</b> {open.name} · made with HyperFrames</span>
              <button type="button" onClick={() => setOpen(null)}>Close</button>
            </div>
          </div>
        )}
      </dialog>
    </div>
  );
};

// A shelf of videos remixed in the Studio app: each card plays HeyGen's remix on hover, credits the original
// (linked to its post), and says how to remix it yourself. Originals are never hosted here.
export const RemixShelf = ({ items, tall = false }) => {
  // Hover previews follow the visitor's reduced-motion setting, known on the first render; the film is a button, so
  // playing it on purpose works for keyboard and touch, and under reduced motion.
  // The setting lives in a ref, not state: a preference change must not re-render the shelf, which would remount
  // every card (RemixCard is declared in here, as Mintlify snippets keep helpers inside the export) and lose a
  // playing film, focus and open instructions.
  const shelfRef = useRef(null);
  const reduced = useRef(null);
  if (reduced.current === null)
    reduced.current = typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const follow = (event) => {
      reduced.current = event.matches;
      // Turned on mid-visit: stop any hover preview that is running.
      if (event.matches) for (const v of shelfRef.current?.querySelectorAll("video") ?? []) if (v.dataset.hover) v.pause();
    };
    query.addEventListener("change", follow);
    return () => query.removeEventListener("change", follow);
  }, []);
  const RemixCard = ({ item }) => {
    const videoRef = useRef(null);
    const [open, setOpen] = useState(false);
    const [copied, setCopied] = useState(false);
    const [chosen, setChosen] = useState(false);
    // One film at a time across the page: any other video starting with sound (another remix, the full-film dialog, a
    // replica pair) is a deliberate choice, so this card stops and lets go of its own.
    useEffect(() => {
      const onPlay = (event) => {
        const v = event.target;
        const own = videoRef.current;
        if (!(v instanceof HTMLVideoElement) || v.muted || v === own || !own) return;
        own.pause();
        own.muted = true;
        setChosen(false);
      };
      document.addEventListener("play", onPlay, true);
      return () => document.removeEventListener("play", onPlay, true);
    }, []);
    const preview = (on) => {
      const v = videoRef.current;
      const filmWithSound = [...document.querySelectorAll("video")].some((x) => !x.paused && !x.muted);
      if (!v || chosen || (on && filmWithSound)) return;
      if (on && !reduced.current) {
        v.dataset.hover = "1";
        v.play().catch(() => {});
      } else if (!on) {
        delete v.dataset.hover;
        v.pause();
        v.currentTime = 0;
      }
    };
    const toggle = () => {
      const v = videoRef.current;
      if (!v) return;
      // A chosen film plays with its sound; hover previews stay muted.
      if (chosen && !v.paused) {
        v.pause();
        v.muted = true;
        setChosen(false);
      } else {
        delete v.dataset.hover;
        v.muted = false;
        v.play().catch(() => {});
        setChosen(true);
      }
    };
    const copy = async () => {
      try {
        await navigator.clipboard.writeText(item.post);
        setCopied(true);
        setTimeout(() => setCopied(false), 1600);
      } catch {}
    };
    return (
      <div className="hf-remix-card overflow-hidden rounded-xl border">
        <button
          type="button"
          className="hf-remix-media relative block w-full cursor-pointer border-0 p-0"
          style={{ aspectRatio: item.ratio }}
          aria-label={`${chosen ? "Pause" : "Play with sound:"} ${item.name}, remixed in HyperFrames`}
          aria-pressed={chosen}
          onMouseEnter={() => preview(true)}
          onMouseLeave={() => preview(false)}
          onClick={toggle}
        >
          <video
            ref={videoRef}
            className="absolute inset-0 h-full w-full object-cover"
            src={item.result}
            poster={item.resultPoster}
            preload="none"
            muted
            loop
            playsInline
          />
        </button>
        <div className="flex flex-col gap-1.5 p-3">
          <strong className="hf-remix-name text-sm leading-snug">{item.name}</strong>
          <span className="hf-remix-credit text-xs">
            Remix of a video by{" "}
            <a href={item.post} target="_blank" rel="noopener noreferrer">{item.handle}</a>
          </span>
          <button
            type="button"
            onClick={() => setOpen(!open)}
            className="hf-remix-btn mt-1 self-start rounded-full px-3 py-1 text-xs font-semibold"
          >
            Remix in Studio
          </button>
          {open && (
            <div className="hf-remix-help text-xs leading-relaxed">
              Copy the original's link, then paste it in <strong>Reference</strong> on the Studio app's Home.{" "}
              <button type="button" onClick={copy} className="font-semibold underline">
                {copied ? "Copied" : "Copy link"}
              </button>
            </div>
          )}
        </div>
      </div>
    );
  };
  return (
    <div ref={shelfRef} className={`hf-remix-shelf not-prose my-6${tall ? " is-tall" : ""}`}>
      {items.map((item) => <RemixCard key={item.id} item={item} />)}
    </div>
  );
};

export const ReplicaCompare = ({
  title,
  meta,
  refSrc,
  refPoster,
  replicaSrc,
  replicaPoster,
}) => {
  const wrapRef = useRef(null);
  const refVideo = useRef(null);
  const repVideo = useRef(null);
  const [muted, setMuted] = useState(true);
  const [inView, setInView] = useState(false);

  // Only assign/decode the two films near the viewport, so the pair doesn't
  // download offscreen. Falls back to eager if there's no observer.
  useEffect(() => {
    const el = wrapRef.current;
    if (!el || typeof IntersectionObserver !== "function") {
      setInView(true);
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => setInView(entries[0]?.isIntersecting ?? false),
      { rootMargin: "200px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Lazy initializer, not a post-mount effect: with useState(false) the first
  // committed render would emit `<video src autoPlay loop>` and only then pull the
  // attributes, so a reduce-motion visitor has already started fetching both films.
  const [reduced, setReduced] = useState(
    () =>
      typeof window !== "undefined" &&
      typeof window.matchMedia === "function" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches,
  );
  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = () => setReduced(query.matches);
    query.addEventListener("change", onChange);
    return () => query.removeEventListener("change", onChange);
  }, []);

  // Off-screen: release both decoded resources — React props alone neither pause
  // an element nor abort its download, so pause() + removeAttribute("src") +
  // load() are all required. On the reduce edge, stop an autoplaying (muted) clip
  // but keep a source assigned so the sound button can still start it: reduced
  // motion disables autoplay, not voluntary playback.
  useEffect(() => {
    const videos = [refVideo.current, repVideo.current];
    if (!inView) {
      for (const video of videos) {
        if (!video) continue;
        video.pause();
        video.muted = true;
        video.removeAttribute("src");
        video.load();
      }
      // Reset the control's state too, so a card unmuted before it scrolled away
      // doesn't return reading "Sound on" over a paused, sourceless pair.
      setMuted(true);
      return;
    }
    if (reduced) {
      for (const video of videos) if (video && video.muted) video.pause();
    }
  }, [reduced, inView]);

  // Keep the replica (right) locked to the reference (left) clock. Attached
  // whenever the pair is in view — including under reduced motion — so that once
  // the reference starts (autoplay, or a voluntary press) the replica follows.
  useEffect(() => {
    const a = refVideo.current;
    const b = repVideo.current;
    if (!a || !b || !inView) return;

    const resync = () => {
      if (Number.isFinite(a.currentTime) && Math.abs((b.currentTime || 0) - a.currentTime) > 0.15) {
        try {
          b.currentTime = a.currentTime;
        } catch {}
      }
      if (a.paused && !b.paused) b.pause();
      if (!a.paused && b.paused) b.play().catch(() => {});
    };
    const onPlay = () => b.play().catch(() => {});
    const onPause = () => b.pause();

    a.addEventListener("timeupdate", resync);
    a.addEventListener("seeked", resync);
    a.addEventListener("play", onPlay);
    a.addEventListener("pause", onPause);
    return () => {
      a.removeEventListener("timeupdate", resync);
      a.removeEventListener("seeked", resync);
      a.removeEventListener("play", onPlay);
      a.removeEventListener("pause", onPause);
    };
  }, [reduced, inView]);

  // Start/pause both films together — the sync effect keeps the replica locked to
  // the reference clock once the reference is playing.
  const startBoth = () => {
    refVideo.current?.play().catch(() => {});
    repVideo.current?.play().catch(() => {});
  };
  const pauseBoth = () => {
    refVideo.current?.pause();
    repVideo.current?.pause();
  };

  const toggleSound = () => {
    const a = refVideo.current;
    if (!a) return;
    const next = !muted;
    setMuted(next);
    a.muted = next; // only the reference carries audio; replica stays silent
    if (!next) {
      startBoth(); // voluntary play — starts the whole pair, incl. under reduced motion
    } else if (reduced) {
      pauseBoth(); // no autoplay to fall back to under reduced motion
    }
  };

  const active = inView && !reduced;

  const card =
    "overflow-hidden rounded-xl border border-zinc-200 bg-white dark:border-zinc-800 dark:bg-zinc-950";
  const video = "aspect-video w-full object-cover bg-zinc-100 dark:bg-zinc-900";
  const cap = "text-xs font-semibold uppercase tracking-wide";

  return (
    <div ref={wrapRef}>
      <div className="mb-3 flex items-baseline justify-between">
        <strong className="text-sm">{title}</strong>
        <span className="text-xs text-zinc-500 dark:text-zinc-400">{meta}</span>
      </div>
      <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
        <div className={`relative ${card}`}>
          <video
            ref={refVideo}
            className={video}
            src={inView ? refSrc : undefined}
            poster={refPoster}
            autoPlay={active}
            muted={muted}
            loop={active}
            playsInline
            preload="none"
          />
          <button
            type="button"
            onClick={toggleSound}
            aria-pressed={!muted}
            aria-label={
              muted
                ? reduced
                  ? "Sound off — play the comparison with sound"
                  : "Sound off — unmute the reference"
                : reduced
                  ? "Sound on — pause the comparison"
                  : "Sound on — mute the reference"
            }
            className="absolute left-3 top-3 z-10 flex items-center gap-1.5 rounded-full bg-black/60 px-3 py-1.5 text-xs font-medium text-white backdrop-blur transition hover:bg-black/75 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white"
          >
            {muted ? (
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 5 6 9H2v6h4l5 4V5z" /><line x1="23" y1="9" x2="17" y2="15" /><line x1="17" y1="9" x2="23" y2="15" /></svg>
            ) : (
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 5 6 9H2v6h4l5 4V5z" /><path d="M15.5 8.5a5 5 0 0 1 0 7" /><path d="M18.5 5.5a9 9 0 0 1 0 13" /></svg>
            )}
            {muted ? "Sound off" : "Sound on"}
          </button>
          <div className="p-3">
            <span className={`${cap} text-zinc-500 dark:text-zinc-400`}>Reference — original film</span>
          </div>
        </div>
        <div className={card}>
          <video
            ref={repVideo}
            className={video}
            src={inView ? replicaSrc : undefined}
            poster={replicaPoster}
            autoPlay={active}
            muted
            loop={active}
            playsInline
            preload="none"
          />
          <div className="p-3">
            <span className={`${cap} text-zinc-700 dark:text-zinc-300`}>HyperFrames replica</span>
          </div>
        </div>
      </div>
    </div>
  );
};
